<?php declare(strict_types=1);require_once dirname(__DIR__,2).'/src/bootstrap.php';Auth::requireLogin();if($_SERVER['REQUEST_METHOD']!=='POST'){http_response_code(405);exit('Method Not Allowed');}Csrf::requireValid($_POST['_token']??null);$id=filter_input(INPUT_POST,'id',FILTER_VALIDATE_INT);if(!$id){flash('error','削除対象が不正です。');redirect('customers/index.php');}$deleted=(new CustomerRepository(Database::connection()))->delete($id);flash($deleted?'success':'error',$deleted?'顧客を削除しました。':'顧客が見つかりません。');redirect('customers/index.php');